func(s *Ros2Std_srvsSrvTriggerServer)SpinOnce(handler func(uint64,Ros2Std_srvsSrvTrigger_Request)(Ros2Std_srvsSrvTrigger_Response,error))error{if s==nil||s.core==nil{return rpcError(ros.BadHandle)};if handler==nil{return rpcError(ros.Invalid)};if err:=s.core.owners.idle();err!=nil{return err};s.core.owners.busy=true;defer func(){s.core.owners.busy=false}();id,value,err:=s.pollInner();if err!=nil{return err};response,err:=handler(id,value);if err!=nil{return err};return s.Respond(id,response)}
// CloseChecked preflights dispatch before any retirement import.
func(s *Ros2Std_srvsSrvTriggerServer)CloseChecked(primary error)RPCCleanup{if s==nil||s.core==nil{return RPCCleanup{Primary:primary,Results:[]error{rpcError(ros.BadHandle)}}};return s.core.cleanup(primary,false)}
// RevokeChecked retains all status results separately from the primary error.
func(s *Ros2Std_srvsSrvTriggerServer)RevokeChecked(primary error)RPCCleanup{if s==nil||s.core==nil{return RPCCleanup{Primary:primary,Results:[]error{rpcError(ros.BadHandle)}}};return s.core.cleanup(primary,true)}
